    /**
     * Handles create a Loan.  if not key provided, calls create, otherwise calls save
     * @param		Loan	loan
     * @return		CompletableFuture<UUID> 
     */
	@PostMapping("/create")
    public CompletableFuture<UUID> create( @RequestBody(required=true) CreateLoanCommand command ) {
		CompletableFuture<UUID> completableFuture = null;
		try {       
        	
			completableFuture = service.createLoan( command );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage(), exc );        	
        }
		
		return completableFuture;
    }

    /**
     * Handles updating a Loan.  if no key provided, calls create, otherwise calls save
     * @param		Loan loan
     * @return		CompletableFuture<Void>
     */
	@PutMapping("/update")
    public CompletableFuture<Void> update( @RequestBody(required=true) UpdateLoanCommand command ) {
		CompletableFuture<Void> completableFuture = null;
		try {                        	        
			// -----------------------------------------------
			// delegate the UpdateLoanCommand
			// -----------------------------------------------
			completableFuture = service.updateLoan(command);;
	    }
	    catch( Throwable exc ) {
	    	LOGGER.log( Level.WARNING, "LoanController:update() - successfully update Loan - " + exc.getMessage());        	
	    }		
		
		return completableFuture;
	}
 
    /**
     * Handles deleting a Loan entity
     * @param		command ${class.getDeleteCommandAlias()}
     * @return		CompletableFuture<Void>
     */
    @DeleteMapping("/delete")    
    public CompletableFuture<Void> delete( @RequestBody(required=true) DeleteLoanCommand command ) {                
    	CompletableFuture<Void> completableFuture = null;
    	try {
        	LoanService delegate = service;

        	completableFuture = delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted Loan with key " + command.getLoanId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }
        
        return completableFuture;
	}        
	
    /**
     * Handles loading a Loan using a UUID
     * @param		UUID uuid 
     * @return		Loan
     */    
    @GetMapping("/load")
    public Loan load( @RequestParam(required=true) UUID uuid ) {    	
    	Loan entity = null;

    	try {  
    		entity = service.getLoan( new LoanFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Loan using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Loan business objects
     * @return		Set<Loan>
     */
    @GetMapping("/")
    public List<Loan> loadAll() {                
    	List<Loan> loanList = null;
        
    	try {
            // load the Loan
            loanList = service.getAllLoan();
            
            if ( loanList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Loans" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Loans ", exc );
        	return null;
        }

        return loanList;
                            
    }

